def asesor_a_vinculo(apps, schema_editor):
    User = apps.get_model("accounts", "User")
    AdvisorLink = apps.get_model("accounts", "AdvisorLink")
    for user in User.objects.exclude(advisor=None).only("id", "advisor_id"):
        AdvisorLink.objects.get_or_create(
            student_id=user.id,
            advisor_id=user.advisor_id,
            course_name="",
            academic_period="",
        )


def dejar_un_codigo_activo(apps, schema_editor):
    """Al revertir: la restricción vieja admitía un solo código activo."""
    AdvisorInviteCode = apps.get_model("accounts", "AdvisorInviteCode")
    vistos = set()
    for invite in AdvisorInviteCode.objects.filter(is_active=True).order_by("-created_at"):
        if invite.owner_id in vistos:
            AdvisorInviteCode.objects.filter(pk=invite.pk).update(is_active=False)
        vistos.add(invite.owner_id)


def vinculo_a_asesor(apps, schema_editor):
    User = apps.get_model("accounts", "User")
    AdvisorLink = apps.get_model("accounts", "AdvisorLink")
    for link in AdvisorLink.objects.order_by("created_at"):
        User.objects.filter(pk=link.student_id, advisor=None).update(
            advisor_id=link.advisor_id,
        )


